    19	    .split(",")
    20	    .map((part) => part.trim())
    21	    .filter((part) => part.length > 0);
    22	  if (tokens.length === 0 || (kind === "POINT" && tokens.length !== 1)) return null;
    23	  const pairs: Array<readonly [number, number]> = [];
    24	  for (const token of tokens) {
    25	    const parts = token.split(/\s+/).filter((part) => part.length > 0);
    26	    const eastText = parts[0];
    27	    const northText = parts[1];
    28	    if (parts.length !== 2 || eastText === undefined || northText === undefined) return null;
