    37	/** GeoJSON from the permit's British National Grid WKT. A bad WKT falls back to the representative point. */
    38	export function geometryFromPermit(permit: StreetManagerPermit): WorkGeometry {
    39	  const fallback = point(permit.location.lon, permit.location.lat);
    40	  const parsed = pairsFromWkt(permit.location.wkt);
    41	  if (!parsed) return fallback;
    42	  const coordinates: Array<[number, number]> = [];
    43	  for (const pair of parsed.pairs) {
    44	    const easting = pair[0];
    45	    const northing = pair[1];
    46	    try {
    47	      const wgs = bngToWgs84(easting, northing);
    48	      coordinates.push([wgs.lon, wgs.lat]);
    49	    } catch {
    50	      return fallback;
    51	    }
    52	  }
    53	  const first = coordinates[0];
    54	  if (!first) return fallback;
    55	  if (parsed.kind === "POINT") return point(first[0], first[1]);
    56	  if (coordinates.length < 2) return fallback;
    57	  return { type: "LineString", coordinates };
    58	}
