   113	
   114	/** Daytime 07:00 to 23:00 is 16 hours. A longer proposed window must include the night. */
   115	const DAYTIME_MS = 16 * 60 * 60 * 1000;
   116	
   117	const NIGHT_WORD = /\bnight\b/i;
   118	
   119	function parseInstant(value: string | null): Date | null {
   120	  if (!value) return null;
   121	  const ms = Date.parse(value);
   122	  if (Number.isNaN(ms)) return null;
   123	  return new Date(ms);
   124	}
   125	
   126	/**
   127	 * True when `[start, end]` overlaps 23:00–07:00 Europe/London.
   128	 * The endpoints are ordered first. A zero-length daytime instant does not count.
   129	 */
   130	export function intervalOverlapsNight(start: Date, end: Date): boolean {
   131	  const earlier = start.getTime() <= end.getTime() ? start : end;
   132	  const later = earlier === start ? end : start;
   133	  if (isInNightWindow(earlier) || isInNightWindow(later)) return true;
   134	  const duration = later.getTime() - earlier.getTime();
   135	  if (duration >= DAYTIME_MS) return true;
   136	  if (duration === 0) return false;
   137	  return toLocalTime(later).minutes < toLocalTime(earlier).minutes;
   138	}
   139	
   140	/**
   141	 * Night work comes from proposed clock times and the traffic management type
   142	 * (`docs/DOMAIN.md`). A date with no clock is not midnight. Actual times are
   143	 * stored on the permit and do not set this flag.
   144	 */
   145	export function isNightWork(schedule: WorkSchedule): boolean {
   146	  if (
   147	    NIGHT_WORD.test(schedule.trafficManagementType) ||
   148	    NIGHT_WORD.test(schedule.currentTrafficManagementType ?? "")
   149	  ) {
   150	    return true;
   151	  }
   152	  const start = parseInstant(schedule.proposedStart.time);
   153	  const end = parseInstant(schedule.proposedEnd.time);
   154	  if (start && end) return intervalOverlapsNight(start, end);
   155	  if (start) return isInNightWindow(start);
   156	  if (end) return isInNightWindow(end);
   157	  return false;
   158	}
   159	
   160	function londonDate(value: string | null): string | null {
   161	  const instant = parseInstant(value);
   162	  if (!instant) return null;
   163	  return toLocalTime(instant).date;
   164	}
   165	
   166	function earliest(dates: readonly string[]): string | null {
   167	  return dates.reduce<string | null>(
   168	    (best, date) => (best === null || date < best ? date : best),
   169	    null,
   170	  );
   171	}
   172	
   173	function latest(dates: readonly string[]): string | null {
   174	  return dates.reduce<string | null>(
   175	    (best, date) => (best === null || date > best ? date : best),
   176	    null,
   177	  );
   178	}
   179	
   180	/**
   181	 * Inclusive London dates the permit occupies. An actual end closes it.
   182	 * Otherwise the proposed end is used. With no end, it stays open from the start.
   183	 */
   184	export function activeDates(schedule: WorkSchedule): { start: string; end: string | null } | null {
   185	  const starts = [
   186	    londonDate(schedule.actualStart),
   187	    londonDate(schedule.proposedStart.time),
   188	    londonDate(schedule.proposedStart.date),
   189	  ].filter((date): date is string => date !== null);
   190	  const proposedEnds = [
   191	    londonDate(schedule.proposedEnd.time),
   192	    londonDate(schedule.proposedEnd.date),
   193	  ].filter((date): date is string => date !== null);
   194	  const actualEnd = londonDate(schedule.actualEnd);
   195	  const start = earliest([...starts, ...proposedEnds, ...(actualEnd ? [actualEnd] : [])]);
   196	  if (!start) return null;
   197	  const end = actualEnd ?? latest(proposedEnds);
   198	  if (end !== null && end < start) return { start: end, end: start };
   199	  return { start, end };
   200	}
   201	
   202	/** True when the permit's active dates overlap the inclusive `[from, to]` range. */
   203	export function overlapsDates(schedule: WorkSchedule, from: string, to: string): boolean {
   204	  const span = activeDates(schedule);
   205	  if (!span) return false;
   206	  if (span.start > to) return false;
   207	  if (span.end !== null && span.end < from) return false;
   208	  return true;
   209	}
