286	  let arc = 0;
287	  let converged = false;
288	  for (let i = 0; i < 10; i++) {
289	    phi += (northing - N0 - arc) / (AIRY_A * F0);
290	    arc = meridianArc(phi);
291	    if (Math.abs(northing - N0 - arc) < 0.00001) {
292	      converged = true;
293	      break;
294	    }
295	  }
296	  if (!converged) {
297	    throw new StreetManagerError("malformed", "National Grid conversion did not converge");
298	  }
299	  const sinPhi = Math.sin(phi);
300	  const cosPhi = Math.cos(phi);
301	  const tanPhi = Math.tan(phi);
302	  const tan2 = tanPhi * tanPhi;
303	  const tan4 = tan2 * tan2;
304	  const tan6 = tan4 * tan2;
305	  const nu = (AIRY_A * F0) / Math.sqrt(1 - AIRY_E2 * sinPhi * sinPhi);
306	  const rho = (AIRY_A * F0 * (1 - AIRY_E2)) / (1 - AIRY_E2 * sinPhi * sinPhi) ** 1.5;
307	  const eta2 = nu / rho - 1;
308	  const vii = tanPhi / (2 * rho * nu);
309	  const viii = (tanPhi / (24 * rho * nu ** 3)) * (5 + 3 * tan2 + eta2 - 9 * tan2 * eta2);
310	  const ix = (tanPhi / (720 * rho * nu ** 5)) * (61 + 90 * tan2 + 45 * tan4);
311	  const x = 1 / cosPhi / nu;
312	  const xi = (1 / cosPhi / (6 * nu ** 3)) * (nu / rho + 2 * tan2);
313	  const xii = (1 / cosPhi / (120 * nu ** 5)) * (5 + 28 * tan2 + 24 * tan4);
314	  const xiia = (1 / cosPhi / (5040 * nu ** 7)) * (61 + 662 * tan2 + 1320 * tan4 + 720 * tan6);
315	  const dE = easting - E0;
316	  const lat = phi - vii * dE ** 2 + viii * dE ** 4 - ix * dE ** 6;
317	  const lon = LON0 + x * dE - xi * dE ** 3 + xii * dE ** 5 - xiia * dE ** 7;
