import { bngToWgs84 } from "../apps/server/src/integrations/street-manager";

// Grey Street Hotel, OSM node 2470415681 in newcastle-overpass.json.
const hotel = { lat: 54.971035, lon: -1.6104655 };

function metres(a: { lat: number; lon: number }, b: { lat: number; lon: number }): number {
  const x = (a.lon - b.lon) * 111_320 * Math.cos((b.lat * Math.PI) / 180);
  const y = (a.lat - b.lat) * 110_540;
  return Math.hypot(x, y);
}

// Newton-style refinement from a rough guess near the sample's Grey Street permit.
let e = 425034;
let n = 564115;
for (let i = 0; i < 8; i++) {
  const w = bngToWgs84(e, n);
  e += (hotel.lon - w.lon) * 111_320 * Math.cos((hotel.lat * Math.PI) / 180);
  n += (hotel.lat - w.lat) * 110_540;
}
console.log("hotel BNG", e.toFixed(1), n.toFixed(1));
for (const [de, dn] of [
  [0, 0],
  [-12, 0],
  [-15, 5],
  [-10, 10],
]) {
  const ee = Math.round(e + de);
  const nn = Math.round(n + dn);
  const w = bngToWgs84(ee, nn);
  console.log(`POINT(${ee} ${nn})`, w.lat.toFixed(6), w.lon.toFixed(6), `${metres(w, hotel).toFixed(1)} m`);
}

