import { scoreHotel } from "@kip/shared/domain";
import { activeDates } from "@kip/shared/works";
import newcastleOverpass from "../apps/server/src/integrations/fixtures/newcastle-overpass.json";
import { parseOverpassPlaces } from "../apps/server/src/integrations/overpass";
import { worksNear } from "../apps/server/src/features/works/query";
import { distanceToWork, memoryWorksRepository, setWorksRepository } from "../apps/server/src/features/works/repo";
import { seedWorks } from "../apps/server/src/features/works/seed";

const repo = memoryWorksRepository();
setWorksRepository(repo);
console.log("tally", await seedWorks());

const hotel = parseOverpassPlaces(newcastleOverpass).find((p) => p.id === "node/2470415681");
if (!hotel) throw new Error("hotel");
const { works } = await worksNear({
  lat: hotel.latitude,
  lon: hotel.longitude,
  radiusM: 200,
  from: "2026-11-20",
  to: "2026-11-21",
});
for (const w of works) {
  console.log(
    w.permitReferenceNumber,
    w.streetName,
    `night=${w.nightWork}`,
    `simulated=${w.simulated}`,
    `${distanceToWork(hotel.latitude, hotel.longitude, w).toFixed(1)} m`,
    JSON.stringify(activeDates(w)),
  );
}

function dates(start: string, end: string): string[] {
  const out: string[] = [];
  for (let d = new Date(`${start}T12:00:00Z`); d.toISOString().slice(0, 10) <= end; d = new Date(d.getTime() + 86_400_000)) {
    out.push(d.toISOString().slice(0, 10));
  }
  return out;
}

const roadworks = works.map((w) => {
  const span = activeDates(w);
  return {
    distanceM: distanceToWork(hotel.latitude, hotel.longitude, w),
    activeDates: span ? dates(span.start, span.end ?? span.start) : [],
    nightWork: w.nightWork,
  };
});
const stayDates = ["2026-11-20", "2026-11-21"];
for (const profile of ["lightSleeper", "nightOut"] as const) {
  const withWorks = scoreHotel({ lnightDb: 55, works: roadworks, stayDates }, profile);
  const without = scoreHotel({ lnightDb: 55, works: [], stayDates }, profile);
  console.log(
    profile,
    "roadworks",
    withWorks.breakdown.roadworks.value,
    `(${withWorks.breakdown.roadworks.detail})`,
    "score",
    withWorks.score.toFixed(1),
    "vs no works",
    without.score.toFixed(1),
  );
}

